using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
namespace Society.Api;

public abstract class CommunityRecord { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } }
public class CommunityPolicy : CommunityRecord { public bool MemberPosting { get; set; } = true; public bool PublicAllowed { get; set; } public bool BlockingAllowed { get; set; } = true; public string PostStages { get; set; } = "[\"activities.approve\"]"; public string EventStages { get; set; } = "[\"events.approve\"]"; public int Revision { get; set; } }
public class ActivityCategory : CommunityRecord { public string Name { get; set; } = ""; public string Kind { get; set; } = "Activity"; public bool Active { get; set; } = true; }
public class ActivityPost : CommunityRecord {
 public Guid AuthorId { get; set; } public Guid? UnitId { get; set; } public Guid? CommitteeId { get; set; } public bool Official { get; set; } public Guid CategoryId { get; set; } public Guid? EventId { get; set; }
 public string Title { get; set; } = ""; public string Body { get; set; } = ""; public string Location { get; set; } = ""; public string[] Tags { get; set; } = []; public Guid[] Mentions { get; set; } = []; public Guid[] Audience { get; set; } = []; public string Visibility { get; set; } = "Chapter";
 public string Status { get; set; } = "Draft"; public string Stages { get; set; } = "[]"; public int Stage { get; set; } public int Revision { get; set; } public bool Featured { get; set; } public bool Achievement { get; set; }
 public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? ScheduledAt { get; set; } public DateTimeOffset? PublishedAt { get; set; }
}
public class CommunityVersion : CommunityRecord { public Guid ResourceId { get; set; } public Guid ActorId { get; set; } public string Kind { get; set; } = "Post"; public int Revision { get; set; } public string Snapshot { get; set; } = "{}"; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class CommunityDecision : CommunityRecord { public Guid ResourceId { get; set; } public Guid ActorId { get; set; } public Guid? UnitId { get; set; } public string Kind { get; set; } = "Post"; public string Decision { get; set; } = ""; public string Permission { get; set; } = ""; public string Roles { get; set; } = "[]"; public string Note { get; set; } = ""; public int Revision { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class ActivityReaction : CommunityRecord { public Guid PostId { get; set; } public Guid UserId { get; set; } public string Kind { get; set; } = "Like"; }
public class ActivityComment : CommunityRecord { public Guid PostId { get; set; } public Guid UserId { get; set; } public Guid? ParentId { get; set; } public string Body { get; set; } = ""; public bool Hidden { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class ActivityBookmark : CommunityRecord { public Guid PostId { get; set; } public Guid UserId { get; set; } }
public class ActivityReport : CommunityRecord { public Guid PostId { get; set; } public Guid UserId { get; set; } public string Reason { get; set; } = ""; public string Status { get; set; } = "Open"; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class CommunityBlock : CommunityRecord { public Guid UserId { get; set; } public Guid BlockedUserId { get; set; } }
public class CommunityMedia : CommunityRecord { public Guid ResourceId { get; set; } public string ResourceKind { get; set; } = "Post"; public string Name { get; set; } = ""; public string ContentType { get; set; } = "image/png"; public int Sort { get; set; } public bool Cover { get; set; } public long Length { get; set; } }
public class CommunityEvent : CommunityRecord {
 public Guid AuthorId { get; set; } public Guid? UnitId { get; set; } public Guid CategoryId { get; set; } public Guid[] CoHosts { get; set; } = []; public string Title { get; set; } = ""; public string Body { get; set; } = ""; public string Venue { get; set; } = ""; public string Mode { get; set; } = "In Person"; public string? OnlineUrl { get; set; } public string TimeZone { get; set; } = "Asia/Kolkata";
 public DateTimeOffset StartsAt { get; set; } public DateTimeOffset EndsAt { get; set; } public DateTimeOffset RegistrationOpens { get; set; } public DateTimeOffset RegistrationCloses { get; set; } public DateTimeOffset? ScheduledAt { get; set; } public DateTimeOffset? PublishedAt { get; set; }
 public string Visibility { get; set; } = "Chapter"; public Guid[] Audience { get; set; } = []; public Guid[] MemberIds { get; set; } = []; public Guid[] CategoryIds { get; set; } = []; public Guid[] CommitteeIds { get; set; } = []; public bool LeadersOnly { get; set; } public bool InvitationOnly { get; set; } public bool AllowGuests { get; set; } public int MaxCompanions { get; set; } public bool RegistrationApproval { get; set; } public int Capacity { get; set; } = 100; public string Questions { get; set; } = "[]";
 public string Status { get; set; } = "Draft"; public string Stages { get; set; } = "[]"; public int Stage { get; set; } public int Revision { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}
public class EventInvitation : CommunityRecord { public Guid EventId { get; set; } public Guid SenderId { get; set; } public Guid? UserId { get; set; } public Guid? MembershipId { get; set; } public string Email { get; set; } = ""; public string Name { get; set; } = ""; public string TokenHash { get; set; } = ""; public string Status { get; set; } = "In App"; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset ExpiresAt { get; set; } public DateTimeOffset? RespondedAt { get; set; } }
