public class EventRegistration : CommunityRecord { public Guid EventId { get; set; } public Guid UserId { get; set; } public Guid? MembershipId { get; set; } public string Name { get; set; } = ""; public string Status { get; set; } = "Pending"; public int Companions { get; set; } public string Answers { get; set; } = "{}"; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; public int Revision { get; set; } }
public class EventPass : CommunityRecord { public Guid EventId { get; set; } public Guid RegistrationId { get; set; } public string TokenHash { get; set; } = ""; public DateTimeOffset IssuedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? RevokedAt { get; set; } }
public class EventAttendance : CommunityRecord { public Guid EventId { get; set; } public Guid RegistrationId { get; set; } public Guid OperatorId { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; public string EntryPoint { get; set; } = "Main entrance"; public bool Voided { get; set; } public string Correction { get; set; } = ""; public int PeopleCount { get; set; } = 1; }

public static class CommunityModel {
 static void Entity<T>(ModelBuilder b) where T:CommunityRecord { b.Entity<T>().HasBaseType((Type?)null); b.Entity<T>().ToTable(typeof(T).Name); b.Entity<T>().HasKey(x=>x.Id); b.Entity<T>().HasAlternateKey(x=>new{x.TenantId,x.Id}); b.Entity<T>().HasOne<Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict); }
 static void Ref<T,U>(ModelBuilder b,string field) where T:CommunityRecord where U:class => b.Entity<T>().HasOne<U>().WithMany().HasForeignKey("TenantId",field).HasPrincipalKey("TenantId","Id").OnDelete(DeleteBehavior.Restrict);
 public static void Configure(ModelBuilder b) {
  Entity<CommunityPolicy>(b); Entity<ActivityCategory>(b); Entity<ActivityPost>(b); Entity<CommunityVersion>(b); Entity<CommunityDecision>(b); Entity<ActivityReaction>(b); Entity<ActivityComment>(b); Entity<ActivityBookmark>(b); Entity<ActivityReport>(b); Entity<CommunityBlock>(b); Entity<CommunityMedia>(b); Entity<CommunityEvent>(b); Entity<EventInvitation>(b); Entity<EventRsvp>(b); Entity<EventRegistration>(b); Entity<EventPass>(b); Entity<EventAttendance>(b);
  b.Entity<CommunityPolicy>().HasIndex(x=>x.TenantId).IsUnique(); b.Entity<ActivityCategory>().HasIndex(x=>new{x.TenantId,x.Kind,x.Name}).IsUnique();
  Ref<ActivityPost,Unit>(b,"UnitId"); Ref<ActivityPost,Committee>(b,"CommitteeId"); Ref<ActivityPost,ActivityCategory>(b,"CategoryId"); Ref<ActivityPost,CommunityEvent>(b,"EventId"); Ref<CommunityEvent,Unit>(b,"UnitId"); Ref<CommunityEvent,ActivityCategory>(b,"CategoryId");
  Ref<ActivityReaction,ActivityPost>(b,"PostId"); Ref<ActivityComment,ActivityPost>(b,"PostId"); Ref<ActivityComment,ActivityComment>(b,"ParentId"); Ref<ActivityBookmark,ActivityPost>(b,"PostId"); Ref<ActivityReport,ActivityPost>(b,"PostId");
  Ref<EventInvitation,CommunityEvent>(b,"EventId"); Ref<EventInvitation,Membership>(b,"MembershipId"); Ref<EventRsvp,CommunityEvent>(b,"EventId"); Ref<EventRegistration,CommunityEvent>(b,"EventId"); Ref<EventRegistration,Membership>(b,"MembershipId"); Ref<EventPass,CommunityEvent>(b,"EventId"); Ref<EventPass,EventRegistration>(b,"RegistrationId"); Ref<EventAttendance,CommunityEvent>(b,"EventId"); Ref<EventAttendance,EventRegistration>(b,"RegistrationId");
  b.Entity<ActivityPost>().HasIndex(x=>new{x.TenantId,x.Status,x.PublishedAt,x.Id}); b.Entity<ActivityPost>().HasIndex(x=>new{x.TenantId,x.UnitId,x.PublishedAt}); b.Entity<ActivityPost>().HasIndex(x=>x.Audience).HasMethod("gin"); b.Entity<CommunityEvent>().HasIndex(x=>new{x.TenantId,x.Status,x.StartsAt}); b.Entity<CommunityEvent>().HasIndex(x=>x.Audience).HasMethod("gin");
  b.Entity<ActivityReaction>().HasIndex(x=>new{x.TenantId,x.PostId,x.UserId}).IsUnique(); b.Entity<ActivityBookmark>().HasIndex(x=>new{x.TenantId,x.PostId,x.UserId}).IsUnique(); b.Entity<ActivityReport>().HasIndex(x=>new{x.TenantId,x.PostId,x.UserId}).IsUnique(); b.Entity<CommunityBlock>().HasIndex(x=>new{x.TenantId,x.UserId,x.BlockedUserId}).IsUnique(); b.Entity<ActivityComment>().HasIndex(x=>new{x.TenantId,x.PostId,x.At});
  b.Entity<EventRsvp>().HasIndex(x=>new{x.TenantId,x.EventId,x.UserId}).IsUnique(); b.Entity<EventRegistration>().HasIndex(x=>new{x.TenantId,x.EventId,x.UserId}).IsUnique(); b.Entity<EventRegistration>().HasIndex(x=>new{x.TenantId,x.EventId,x.Status,x.At}); b.Entity<EventInvitation>().HasIndex(x=>new{x.TenantId,x.EventId,x.Email}).IsUnique(); b.Entity<EventInvitation>().HasIndex(x=>x.TokenHash).IsUnique(); b.Entity<EventPass>().HasIndex(x=>x.TokenHash).IsUnique(); b.Entity<EventAttendance>().HasIndex(x=>new{x.TenantId,x.EventId,x.RegistrationId}).IsUnique();
  b.Entity<CommunityPolicy>().Property(x=>x.Revision).IsConcurrencyToken(); b.Entity<ActivityPost>().Property(x=>x.Revision).IsConcurrencyToken(); b.Entity<CommunityEvent>().Property(x=>x.Revision).IsConcurrencyToken(); b.Entity<EventRegistration>().Property(x=>x.Revision).IsConcurrencyToken();
 }
}
public record PostWrite(Guid? UnitId, Guid CategoryId, [Required,MaxLength(20000)] string Body, string Title="", bool Official=false, Guid? CommitteeId=null, string Visibility="Chapter", Guid[]? Audience=null, Guid? EventId=null, string Location="", string[]? Tags=null, Guid[]? Mentions=null, DateTimeOffset? ScheduledAt=null, bool Submit=false, bool Achievement=false, int Revision=0);
public record CommunityReview(string Decision,string Note,int Revision);
public record EventWrite(Guid? UnitId,Guid CategoryId,[Required,MaxLength(180)]string Title,[Required,MaxLength(20000)]string Body,DateTimeOffset StartsAt,DateTimeOffset EndsAt,DateTimeOffset RegistrationOpens,DateTimeOffset RegistrationCloses,string Venue="",string Mode="In Person",string? OnlineUrl=null,string TimeZone="Asia/Kolkata",int Capacity=100,bool AllowGuests=false,int MaxCompanions=0,bool RegistrationApproval=false,bool InvitationOnly=false,string Visibility="Chapter",Guid[]? Audience=null,Guid[]? MemberIds=null,Guid[]? CategoryIds=null,Guid[]? CommitteeIds=null,bool LeadersOnly=false,Guid[]? CoHosts=null,string Questions="[]",DateTimeOffset? ScheduledAt=null,bool Submit=false,int Revision=0);
public record CommentWrite([Required,MaxLength(2000)]string Body,Guid? ParentId=null,Guid[]? Mentions=null);
public record ReactionWrite(string Kind); public record ReportWrite([Required,MaxLength(1000)]string Reason); public record RegisterEvent(int Companions=0,string Answers="{}",string? InvitationToken=null); public record InviteEvent(Guid[]? MembershipIds=null,string[]? GuestEmails=null,string Channel="In App",int Days=7); public record CheckInEvent(string? Token,Guid? RegistrationId,string EntryPoint="Main entrance",int PeopleCount=1);
